0 * {{Niemand kommt}}
1 one {{{$host} kommt}}
1 * {{{$host} kommt}}
* one {{{$host} und {$guests_minus_1} weitere Person kommen}}
* * {{{$host} und {$guests_minus_1} weitere Personen kommen}}

.input {$likes :number}
.local $likes_minus_2 = {$likes :offset subtract=2}
.match $likes_minus_2
